class Solution {
public:
    int numberOfPairs(vector<vector<int>>& points) {
        sort(points.begin(), points.end(), [](const vector<int>& a, const vector<int>& b) {
            if (a[0] != b[0]) return a[0] < b[0];
            return a[1] > b[1];
        });
        int n = points.size(), count = 0;
        for (int i = 0; i < n; ++i) {
            int maxY = INT_MIN;
            for (int j = i + 1; j < n; ++j) {
                int yj = points[j][1];
                if (yj <= maxY) continue;
                if (yj <= points[i][1]) {
                    ++count;
                    maxY = yj;
                }
            }
        }
        return count;
    }
};
